import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第十二章 什么欲望是世间排名第一的欲望？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/12第十二章 什么欲望是世间排名第一的欲望.md","filePath":"meditation/巴利文大藏经/12第十二章 什么欲望是世间排名第一的欲望.md"}'),o={name:"meditation/巴利文大藏经/12第十二章 什么欲望是世间排名第一的欲望.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第十二章-什么欲望是世间排名第一的欲望" tabindex="-1">第十二章 什么欲望是世间排名第一的欲望？ <a class="header-anchor" href="#第十二章-什么欲望是世间排名第一的欲望" aria-label="Permalink to &quot;第十二章 什么欲望是世间排名第一的欲望？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部3相应12经/五位国王经(憍萨罗相应/有偈篇/祇夜)</p><p>有个时候，以波斯匿王为首的五位国王正在讨论一个问题：「什么欲望是最让人贪爱不舍、恋恋不忘，排名第一的欲望呢？」</p><p>五位国王有各自的说法，其中有位国王说：「眼睛看见的事物，比如看见黄金珠宝，看见国色天香的女子，看见等等的事物就是最让人陶醉，最让人贪爱不舍，排名第一的欲望。」</p><p>有一位国王说：「耳朵听到的声音，比如听到美妙的琴声，听到鸟儿清脆的叫声，听到等等的声音就是最让人陶醉，最让人贪爱不舍，排名第一的欲望。」</p><p>某一位国王说：「鼻子闻到的气味，比如闻到沁人心脾的花香，闻到清香四溢的酒香，闻到等等的气味就是最让人陶醉，最让人贪爱不舍，排名第一的欲望。」</p><p>某一位国王说：「舌头尝到的味道，比如尝到甘脆爽口的酥饼，尝到唇齿留香的佳肴，尝到等等的味道就是最让人陶醉，最让人贪爱不舍，排名第一的欲望。」</p><p>某一位国王说：「身体触摸到事物产生的触觉，比如摸到绒毛，摸到柔嫩肌肤，摸到事物后产生的等等触觉就是最让人陶醉，最让人贪爱不舍，排名第一的欲望。」</p><p>五位国王互相辩论，想要说服对方接受自己的观点，可是争论了很长的时间也没有一个结果，于是波斯匿王就对这些国王说：“诸位大王，我们现在争论了这么久，都没有办法解决这个问题，我们不如一同去请教世尊吧，请世尊为我们排除内心的疑惑吧。”</p><p>“波斯匿王，也只有这样办了，我们一同前去拜见世尊吧。”这些国王都异口同声的回答波斯匿王。</p><p>那时，以波斯匿王为首的五位国王就一同来到佛陀的住所，他们顶礼佛陀后，在一旁坐好，波斯匿王对佛陀说：“世尊，我们有一个问题想要请教您。世尊，是这样的，刚才我们在争论一个问题，这个问题是：「什么欲望是最让人贪爱不舍、恋恋不忘，排名第一的欲望呢？」我们之间有不同的说法，有的人说：眼睛看见的事物是最让人陶醉，最让人贪爱不舍，排名第一的欲望。有的人说：耳朵听到的声音是最让人陶醉，最让人贪爱不舍，排名第一的欲望。有的人说：鼻子闻到的气味最让人贪爱不舍，排名第一的欲望。有的人说：舌头尝到的味道是最让人陶醉，最让人贪爱不舍，排名第一的欲望。有的人说：身体触摸到事物产生的触觉是最让人贪爱不舍，排名第一的欲望。</p><p>世尊，我们为这个问题争论不休，谁都无法说服谁，世尊，到底什么欲望才是最让人贪爱不舍，排名第一的欲望呢？请您为我们解除疑惑。”</p><p>佛陀说：“大王，如来认为：「世间人内心所想的，他们内心最喜欢，最贪爱的事物，就是最让他们陶醉，最让他们贪爱不舍，排名第一的欲望。」</p><p>是什么意思呢？</p><p>大王，眼睛看见同样的事物，比如看见黄金珠宝，看见闭月羞花的女子，看见等等的事物，对于某一些人来说，他们看见后会认为很合自己的意，他们认为看见的这些事物是最吸引他们，最让他们陶醉，最让他们贪爱不舍的事物，对于另一些人来说，他们看见这些事物后，不会认为这些事物能够吸引他们，不会认为这些事物完全合他们自己的意，不会认为这些事物是最吸引他们，最让他们陶醉，最让他们贪爱不舍的事物。大王，那些对眼睛看见的事物开心喜悦、非常满意的人，当他们被眼睛看见的事物吸引后，不会再被其他的事物所吸引，不会再去贪求其他任何的事物，那么对于他们来说当前这个吸引他们，让他们陶醉、贪爱不舍的事物就是他们内心中排行第一的欲望，这些事物对于他们来说胜过其他任何的事物，所以如来说世间人内心所想的，内心最喜欢，最贪爱的事物就是最让他们陶醉，最让他们贪爱不舍，排名第一的欲望。</p><p>大王，耳朵听到同样的声音，比如听到美妙的琴声，听到鸟儿清脆的叫声，听到等等的声音，对于某一些人来说，他们听到后会认为很合自己的意，他们认为听到的这些声音是最吸引他们，最让他们陶醉，最让他们贪爱不舍的事物，对于另一些人来说，他们听到这些声音后，不会认为这些声音能够吸引他们，不会认为这些声音完全合他们自己的意，不会认为这些声音是最吸引他们，最让他们陶醉，最让他们贪爱不舍的事物。大王，那些对耳朵听到的声音开心喜悦、非常满意的人，当他们被耳朵听到的声音吸引后，不会再被其他的事物所吸引，不会再去贪求其他任何的事物，那么对于他们来说当前这个吸引他们，让他们陶醉、贪爱不舍的声音就是他们内心中排行第一的欲望，这些声音对于他们来说胜过其他任何的事物，所以如来说世间人内心所想的，内心最喜欢，最贪爱的事物就是最让他们陶醉，最让他们贪爱不舍，排名第一的欲望。</p><p>大王，鼻子闻到同样的气味，比如闻到沁人心脾的花香，闻到清香四溢的酒香，闻到等等的气味，对于某一些人来说，他们闻到后会认为很合自己的意，他们认为闻到的这些气味是最吸引他们，最让他们陶醉，最让他们贪爱不舍的事物，对于另一些人来说，他们闻到这些气味后，不会认为这些气味能够吸引他们，不会认为这些气味完全合他们自己的意，不会认为这些气味是最吸引他们，最让他们陶醉，最让他们贪爱不舍的事物。大王，那些对鼻子闻到的气味开心喜悦、非常满意的人，当他们被鼻子闻到的气味吸引后，不会再被其他的事物所吸引，不会再去贪求其他任何的事物，那么对于他们来说当前这个吸引他们，让他们陶醉、贪爱不舍的气味就是他们内心中排行第一的欲望，这些气味对于他们来说胜过其他任何的事物，所以如来说世间人内心所想的，内心最喜欢，最贪爱的事物就是最让他们陶醉，最让他们贪爱不舍，排名第一的欲望。</p><p>大王，舌头尝到同样的味道，比如尝到甘脆爽口的酥饼，尝到唇齿留香的佳肴，尝到等等的味道，对于某一些人来说，他们尝到后会认为很合自己的意，他们认为尝到的这些味道是最吸引他们，最让他们陶醉，最让他们贪爱不舍的事物，对于另一些人来说，他们尝到这些味道后，不会认为这些味道能够吸引他们，不会认为这些味道完全合他们自己的意，不会认为这些味道是最吸引他们，最让他们陶醉，最让他们贪爱不舍的事物。大王，那些对舌头尝到的味道开心喜悦、非常满意的人，当他们被舌头尝到的味道吸引后，不会再被其他的事物所吸引，不会再去贪求其他任何的事物，那么对于他们来说当前这个吸引他们，让他们陶醉、贪爱不舍的味道就是他们内心中排行第一的欲望，这些味道对于他们来说胜过其他任何的事物，所以如来说世间人内心所想的，内心最喜欢，最贪爱的事物就是最让他们陶醉，最让他们贪爱不舍，排名第一的欲望。</p><p>大王，身体触摸到事物产生同样的触觉，比如摸到绒毛，摸到柔嫩肌肤，摸到事物产生的等等触觉，对于某一些人来说，他们触摸到后会认为很合自己的意，他们认为触摸到的这些触觉是最吸引他们，最让他们陶醉，最让他们贪爱不舍的事物，对于另一些人来说，他们触摸到这些触觉后，不会认为这些触觉能够吸引他们，不会认为这些触觉完全合他们自己的意，不会认为这些触摸到的触觉是最吸引他们，最让他们陶醉，最让他们贪爱不舍的事物。大王，那些对身体触摸到事物产生的触觉开心喜悦、非常满意的人，当他们被身体触摸到的触觉吸引后，不会再被其他的事物所吸引，不会再去贪求其他任何的事物，那么对于他们来说当前这个吸引他们，让他们陶醉、贪爱不舍的触觉就是他们内心中排行第一的欲望，这些触觉对于他们来说胜过其他任何的事物，所以如来说世间人内心所想的，内心最喜欢，最贪爱的事物就是最让他们陶醉，最让他们贪爱不舍，排名第一的欲望。”</p><p>当时，有位叫栴檀额利迦的在家修行居士坐在众人中听佛陀说法。那时，栴檀额利迦居士听完佛陀说法后，就从座位上站起来，他将上衣整理好放在肩膀的一边，向佛陀合掌鞠躬，他对佛陀和在座听法的人说：“世尊，诸位在座的大德们，您们现在心中不要想其他的事情，就在您们心中想想我现在的样子吧，您们一心一意、专心致志的只想我现在的形貌和样子，就不会去想其他的事情了。”</p><p>佛陀对栴檀额利迦居士说：“栴檀额利迦，你正在宣说如来的正法。”</p><p>在座听法的很多人疑惑的问佛陀：“世尊，栴檀额利迦居士他刚才说的那句话是什么意思呢？世尊，为什么您说他正在宣说您的正法呢？我们都弄不懂他在说什么哦！请世尊您为我们解除疑惑。”</p><p>佛陀说：“栴檀额利迦刚才所说言语的意思是，想让你们不要再继续纠缠「什么欲望才是世间排名第一的欲望？」这个问题，他是想让你们不要再在内心中生起问这个问题的念想，是想让你们不要再在内心中生起求取这个问题答案的念想，这样你们就从问这个问题，寻找这个问题答案的烦恼中解脱了出来，你们内心生起问问题、寻求解答的念想，就是掉进了烦恼的陷阱，栴檀额利迦是想让你们从问这个问题、寻求这个问题解答的烦恼陷阱中跳出来，他让你们一心一意、专心致志的只在内心中想他的形貌和样子，就是想让你们不要在内心中再次生起问这个问题、寻求这个问题解答的念想，你们问问题、寻求解答的念想不再内心中生起了，这个问问题、寻求解答的烦恼也就除灭、消失不见了，当然他让你们内心中只想他形貌样子的做法，也是让你们生起烦恼，不过这个烦恼比你们问问题、寻找答案的烦恼要小很多，他不过是用小烦恼来替换掉你们的大烦恼。内心不生起、不挂念和执着任何的念想，烦恼和痛苦就无法束缚捆绑你们，就无法侵害烦扰您们。”</p><p>栴檀额利迦居士此时赞叹佛陀说到：“如来如同清净芬芳的红莲花，会在早晨盛开芳香四溢；如来是放出光明的圣者，如同光芒四射的太阳那样在空中照亮世间万物。”</p><p>这时，栴檀额利迦居士说偈言：</p><p>「芳香赤莲华，晨开香不去。</p><p>见鸯耆罗光，映空如太阳。」</p><p>那时，五位在座听法的国王，他们将自己身上穿的华贵衣服脱下来供养给栴檀额利迦居士，栴檀额利迦居士又将五位国王的衣服都供养给了佛陀。</p>',29)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
